<?php
declare(strict_types=1);require_once dirname(__DIR__).'/config/bootstrap.php';require_permission('credit.view');$rows=db()->query('SELECT c.id,c.name,c.phone,c.credit_limit,c.account_balance,COUNT(s.id) invoice_count,MIN(CASE WHEN s.balance_due>0 THEN s.sale_date END) oldest_debt FROM customers c LEFT JOIN sales s ON s.customer_id=c.id AND s.status="completed" AND s.balance_due>0 WHERE c.account_balance>0 GROUP BY c.id ORDER BY c.account_balance DESC')->fetchAll();$total=db()->query('SELECT COALESCE(SUM(account_balance),0) FROM customers WHERE account_balance>0')->fetchColumn();$pageTitle='Debtors';$pageStyles=['admin.css','commerce.css'];require BASE_PATH.'/includes/header.php';require BASE_PATH.'/includes/sidebar.php';?>
<div class="app-main"><?php require BASE_PATH.'/includes/navbar.php';?><main class="content"><?php require BASE_PATH.'/includes/alerts.php';?><div class="page-toolbar"><div><span class="eyebrow">Credit control</span><h2>Debtors</h2><p>Customers with outstanding credit balances.</p></div></div><section class="mini-metric-grid"><article class="mini-metric"><span>Total debtors</span><strong><?=e((string)count($rows))?></strong></article><article class="mini-metric"><span>Outstanding debt</span><strong><?=e(money($total))?></strong></article></section><section class="panel-card table-panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Customer</th><th>Phone</th><th>Invoices</th><th>Credit limit</th><th>Outstanding</th><th>Oldest debt</th><th></th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7"><div class="empty-state"><strong>No outstanding customer debt</strong></div></td></tr><?php else:foreach($rows as$r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['phone']?:'—')?></td><td><?=e((string)$r['invoice_count'])?></td><td><?=e(money($r['credit_limit']))?></td><td><strong class="text-warning"><?=e(money($r['account_balance']))?></strong></td><td><?=e(format_datetime($r['oldest_debt'],'d M Y'))?></td><td class="table-action-cell"><a class="table-action" href="<?=e(app_url('customers/view.php?id='.(int)$r['id']))?>">View</a></td></tr><?php endforeach;endif;?></tbody></table></div></section></main></div><?php require BASE_PATH.'/includes/footer.php';?>
